# =============================================================================
# SCRIPT LOGIC
# =============================================================================

async def main():
    print("=" * 70)
    print("Phase 2: Import Comprehensive Laws, Articles, and Court Cases")
    print("=" * 70)

    # Step 1: Create database tables if they don't exist
    print("\n[1/5] Creating database tables...")
    try:
        async with engine.begin() as conn:
            await conn.run_sync(Base.metadata.create_all)
        print("  Database tables ready.")
    except Exception as e:
        print(f"  ERROR creating tables: {e}")
        traceback.print_exc()
        return

    # Step 2: Import laws and articles to PostgreSQL
    print("\n[2/5] Importing laws and articles to PostgreSQL...")
    total_laws = 0
    total_articles = 0
    skipped_articles = 0
    try:
        async with async_session_factory() as session:
            for law_key, law_data in COMPREHENSIVE_LAWS.items():
                meta = law_data["meta"]
                articles = law_data["articles"]

                # Check if law already exists
                result = await session.execute(
                    select(Law).where(Law.name == meta["name"])
                )
                law_record = result.scalar_one_or_none()

                if law_record is None:
                    law_record = Law(
                        id=str(uuid.uuid4()),
                        name=meta["name"],
                        short_name=meta["short_name"],
                        law_type=meta["law_type"],
                        category=meta["category"],
                        effective_date=meta["effective_date"],
                        status=meta["status"],
                        issuing_authority=meta["issuing_authority"],
                        abstract=meta["abstract"],
                    )
                    session.add(law_record)
                    await session.flush()
                    total_laws += 1
                    print(f"  [+] Law: {meta['name']}")
                else:
                    print(f"  [=] Law already exists: {meta['name']}")

                # Insert articles
                for art in articles:
                    existing = await session.execute(
                        select(LegalArticle).where(
                            LegalArticle.law_id == law_record.id,
                            LegalArticle.article_number == art["num"],
                        )
                    )
                    if existing.scalar_one_or_none() is not None:
                        skipped_articles += 1
                        continue

                    article = LegalArticle(
                        id=str(uuid.uuid4()),
                        law_id=law_record.id,
                        article_number=art["num"],
                        title=art.get("title", ""),
                        content=art["content"],
                        chapter=art.get("chapter", ""),
                        section=art.get("section", ""),
                        effective_status="active",
                        tags=art.get("tags", ""),
                    )
                    session.add(article)
                    total_articles += 1

                print(f"    -> {len(articles)} articles processed")

            await session.commit()
    except Exception as e:
        print(f"  ERROR importing laws: {e}")
        traceback.print_exc()

    print(f"  Laws created: {total_laws}")
    print(f"  Articles created: {total_articles}")
    print(f"  Articles skipped (duplicates): {skipped_articles}")

    # Step 3: Import court cases to PostgreSQL
    print("\n[3/5] Importing court cases to PostgreSQL...")
    total_cases = 0
    skipped_cases = 0
    try:
        async with async_session_factory() as session:
            for case in COURT_CASES:
                existing = await session.execute(
                    select(CourtCase).where(CourtCase.case_number == case["case_number"])
                )
                if existing.scalar_one_or_none() is not None:
                    skipped_cases += 1
                    continue

                court_case = CourtCase(
                    id=str(uuid.uuid4()),
                    case_number=case["case_number"],
                    title=case["title"],
                    court_name=case.get("court_name", ""),
                    case_type=case.get("case_type", ""),
                    cause_of_action=case.get("cause_of_action", ""),
                    decision_date=case.get("decision_date", ""),
                    parties=case.get("parties", ""),
                    summary=case.get("summary", ""),
                    full_text=case.get("full_text", ""),
                    key_points=case.get("key_points", ""),
                    referenced_laws=case.get("referenced_laws", ""),
                    judgment_result=case.get("judgment_result", ""),
                    tags=case.get("tags", ""),
                    doc_count=case.get("doc_count", 0),
                )
                session.add(court_case)
                total_cases += 1

            await session.commit()
    except Exception as e:
        print(f"  ERROR importing court cases: {e}")
        traceback.print_exc()

    print(f"  Cases created: {total_cases}")
    print(f"  Cases skipped (duplicates): {skipped_cases}")

    # Step 4: Generate embeddings and import to ChromaDB
    print("\n[4/5] Generating embeddings and importing to ChromaDB...")
    try:
        import chromadb
        chroma_client = chromadb.PersistentClient(path="./chroma_data")
        collection = chroma_client.get_or_create_collection(
            name="legal_articles",
            metadata={"hnsw:space": "cosine"},
        )
        print(f"  ChromaDB collection 'legal_articles' ready (existing items: {collection.count()})")

        # Read all articles from DB for embedding
        print("  Reading all articles from database...")
        all_articles = []
        async with async_session_factory() as session:
            result = await session.execute(
                select(LegalArticle, Law).join(Law, LegalArticle.law_id == Law.id)
            )
            rows = result.all()
            for article, law in rows:
                all_articles.append((article, law))

        print(f"  Found {len(all_articles)} articles to embed")

        if all_articles:
            # Clear existing data in collection
            existing_ids = list(collection.get()["ids"])
            if existing_ids:
                print(f"  Clearing {len(existing_ids)} existing items from collection...")
                for i in range(0, len(existing_ids), 500):
                    collection.delete(ids=existing_ids[i:i+500])

            # Batch embed and insert
            batch_size = 32
            all_docs = []
            all_metadatas = []
            all_ids = []

            for article, law in all_articles:
                doc_text = f"{law.name} {article.article_number} {article.title or ''} {article.content}"
                all_docs.append(doc_text)
                all_metadatas.append({
                    "law_name": law.name,
                    "article_number": article.article_number,
                    "title": article.title or "",
                    "content": article.content[:500],
                    "chapter": article.chapter or "",
                    "tags": article.tags or "",
                    "law_type": law.law_type,
                    "category": law.category or "",
                })
                all_ids.append(f"{law.short_name or law.name}_{article.article_number}")

            print(f"  Generating embeddings in batches of {batch_size}...")
            for i in range(0, len(all_docs), batch_size):
                batch_docs = all_docs[i:i+batch_size]
                batch_ids = all_ids[i:i+batch_size]
                batch_metas = all_metadatas[i:i+batch_size]

                embeddings = await ModelRegistry.embed_texts(batch_docs)

                # ChromaDB limits batch to ~4166 items
                for j in range(0, len(batch_docs), 4000):
                    collection.add(
                        documents=batch_docs[j:j+4000],
                        embeddings=embeddings[j:j+4000],
                        metadatas=batch_metas[j:j+4000],
                        ids=batch_ids[j:j+4000],
                    )

                if (i // batch_size + 1) % 10 == 0:
                    print(f"    -> Processed {min(i + batch_size, len(all_docs))} / {len(all_docs)} articles")

            print(f"  Successfully embedded and stored {len(all_docs)} articles in ChromaDB")
    except ImportError:
        print("  WARNING: chromadb not installed, skipping vector import")
    except Exception as e:
        print(f"  ERROR during embedding/import: {e}")
        traceback.print_exc()

    # Step 5: Summary
    print("\n[5/5] Summary")
    print("=" * 70)
    print(f"  Laws imported:          {total_laws}")
    print(f"  Articles imported:      {total_articles}")
    print(f"  Articles skipped:       {skipped_articles}")
    print(f"  Court cases imported:   {total_cases}")
    print(f"  Court cases skipped:    {skipped_cases}")
    if all_articles:
        print(f"  Embeddings generated:   {len(all_docs)}")
    print("=" * 70)
    print("Import complete!")


if __name__ == "__main__":
    asyncio.run(main())
